2164	void AGBHUD::DrawSkillTrees(AGBPlayerCharacter* Player, EGBHudSkin Skin, float X, float Y, float W, float H)
2165	{
2166		using namespace GBHudMenuLocal;
2167		const float S = UIScale();
2168		const float P = ArtPixel();
2169		const UGBDataSubsystem* Data = UGBDataSubsystem::Get(this);
2170		const UGBSkillTreeComponent* SkillTree = Player->GetSkillTree();
2171		if (!SkillTree)
2172		{
2173			return;
2174		}
2175		const TArray<FSkillNodeRef> Nodes = GetSkillNodes();
2176		const bool bCyber = Skin == EGBHudSkin::Cyberpunk;
2177	
2178		// Top row: points in the middle, "+1 skill point" (test) on the left, reset on the right.
2179		{
2180			const int32 Points = SkillTree->GetPoints();
2181			const FString PointsText = FString::Printf(TEXT("%d"), Points);
2182			const float RowY = Y;
2183			const float BtnH = bCyber ? 36.f * S : 13.f * P;
2184			const float CX = X + W * 0.5f;
2185			const FVector2D LabelSize = UiMeasure(Skin, EGBTextSize::Small, TEXT("SKILL POINTS"));
2186			const FVector2D NumSize = UiMeasure(Skin, EGBTextSize::Heading, PointsText);
2187			const float GroupW = LabelSize.X + (bCyber ? 14.f * S : 4.f * P) + NumSize.X;
2188			UiText(Skin, EGBTextSize::Small, EGBTextTone::Muted, TEXT("SKILL POINTS"), CX - GroupW * 0.5f, RowY + (BtnH - LabelSize.Y) * 0.5f);
2189			UiText(Skin, EGBTextSize::Heading, Points > 0 ? EGBTextTone::Warn : EGBTextTone::Accent, PointsText, CX + GroupW * 0.5f - NumSize.X, RowY + (BtnH - NumSize.Y) * 0.5f);
2190			const int32 Spent = SkillTree->GetPointsSpent();
2191			const FString ResetText = FString::Printf(TEXT("Reset skills (+%d)"), Spent);
2192			const FString AddText(TEXT("+1 skill point"));
2193			const float ResetW = UiMeasure(Skin, EGBTextSize::Small, ResetText).X + (bCyber ? 40.f * S : 14.f * P);
2194			const float AddW = UiMeasure(Skin, EGBTextSize::Small, AddText).X + (bCyber ? 40.f * S : 14.f * P);
2195			const float Margin = bCyber ? 40.f * S : 12.f * P;
2196			const float ResetX = CX + GroupW * 0.5f + Margin;
2197			const float AddX = CX - GroupW * 0.5f - Margin - AddW;
2198			MenuButton(Skin, ResetX, RowY, ResetW, BtnH, ResetText, Spent > 0, IsMouseOver(ResetX, RowY, ResetW, BtnH));
2199			AddMenuHit(EMenuHitKind::SkillReset, ResetX, RowY, ResetW, BtnH);
2200			MenuButton(Skin, AddX, RowY, AddW, BtnH, AddText, true, IsMouseOver(AddX, RowY, AddW, BtnH));
2201			AddMenuHit(EMenuHitKind::SkillAddPoint, AddX, RowY, AddW, BtnH);
2202			Y += BtnH + (bCyber ? 18.f * S : 6.f * P);
2203			H -= BtnH + (bCyber ? 18.f * S : 6.f * P);
2204		}
2205		if (Nodes.Num() == 0)
2206		{
2207			UiText(Skin, EGBTextSize::Body, EGBTextTone::Muted, TEXT("No skills defined (Skills.json)."), X + W * 0.5f, Y + 20.f * S, 0.5f);
2208			return;
2209		}
2210		const FSkillNodeRef* Selected = Nodes.FindByPredicate([this](const FSkillNodeRef& Node) { return Node.Id == MenuState.SkillCursor; });
2211		if (!Selected)
2212		{
2213			MenuState.SkillCursor = Nodes[0].Id;
2214			Selected = &Nodes[0];
2215		}
2216	
2217		// GDD 13: the spell tree has the 90s RPG look, the weapon tree the cyberpunk look, whatever the held item.
2218		const float DetailH = FMath::RoundToFloat(FMath::Max(110.f * S, 26.f * P));
2219		const float Gap = FMath::RoundToFloat(W * 0.02f);
2220		const float AreaW = FMath::RoundToFloat((W - Gap) * 0.5f);
2221		const float AreaY = Y;
2222		const float AreaH = FMath::Max(100.f * S, H - DetailH - 12.f * S);
2223		static const TCHAR* Titles[] = { TEXT("SPELLS"), TEXT("WEAPONS") };
2224	
2225		for (int32 Tree = 0; Tree < 2; ++Tree)
2226		{
2227			const float AX = X + Tree * (AreaW + Gap);
2228			const bool bTreeCyber = Tree == 1;
2229			const EGBHudSkin TreeSkin = bTreeCyber ? EGBHudSkin::Cyberpunk : EGBHudSkin::Rpg90s;
2230			float GridTop = AreaY;
2231			if (bTreeCyber)
2232			{
2233				CyBox(AX, AreaY, AreaW, AreaH, 22.f * S, GBAlpha(GBCy::Ink, 0.92f), GBAlpha(GBCy::RedDim, 0.9f), 0x5);
2234				CyScanlines(AX, AreaY, AreaW, AreaH, 0.25f);
2235				DrawGlow(AX + AreaW * 0.5f, AreaY, AreaW * 0.6f, AreaH * 0.4f, GBAlpha(GBCy::Red, 0.08f));
2236				FCyTextStyle TitleStyle;
2237				TitleStyle.Face = ECyFace::Condensed;
2238				TitleStyle.Px = 26.f;
2239				TitleStyle.Spacing = 200;
2240				TitleStyle.bUpper = true;
2241				TitleStyle.Color = GBCy::Red;
2242				const FVector2D TS = DrawCyText(Titles[Tree], AX + 26.f * S, AreaY + 16.f * S, TitleStyle, 0.f);
2243				FCyTextStyle Sub;
2244				Sub.Face = ECyFace::Mono;
2245				Sub.Px = 12.f;
2246				Sub.Color = GBCy::RedDim;
2247				DrawCyText(TEXT("// FIREARMS PERKS"), AX + 26.f * S + TS.X + 14.f * S, AreaY + 26.f * S, Sub, 0.f);
2248				CyRuler(AX + 26.f * S, AreaY + 16.f * S + TS.Y + 8.f * S, AreaW - 52.f * S, GBAlpha(GBCy::RedDim, 0.7f));
2249				GridTop = AreaY + 16.f * S + TS.Y + 30.f * S;
2250			}
2251			else
2252			{
2253				const float PX = FMath::RoundToFloat(AX / P) * P;
2254				const float PY = FMath::RoundToFloat(AreaY / P) * P;
2255				const float PW = FMath::RoundToFloat(AreaW / P) * P;
2256				const float PH = FMath::RoundToFloat(AreaH / P) * P;
2257				FillRect(PX, PY, PW, PH, GBRpg::Stone1);
2258				RpgStone(PX, PY, PW, PH);
2259				DrawGlow(PX + PW * 0.5f, PY + PH * 0.35f, PW * 0.6f, PH * 0.6f, FLinearColor(0.35f, 0.2f, 0.1f, 0.12f));
2260				RpgFrame(PX, PY, PW, PH, ERpgFrame::Iron);
2261				DrawOutline(PX + 4.f * P, PY + 4.f * P, PW - 8.f * P, PH - 8.f * P, GBRpg::Gold1, P);
2262				const int32 HeadScale = FMath::Max(2, FMath::RoundToInt(4.f * S));
2263				FPixelTextStyle Head;
2264				Head.Scale = HeadScale;
2265				Head.Ink = &GBRpg::InkGold;
2266				Head.Outline = GBRpg::Outline;
2267				Head.Shadow = FLinearColor(0.f, 0.f, 0.f, 0.7f);
2268				DrawPixelText(Titles[Tree], PX + PW * 0.5f, PY + 8.f * P, Head, 0.5f);
2269				GridTop = PY + 8.f * P + 7.f * HeadScale + 6.f * P;
2270			}
2271	
2272			int32 MaxColumn = 0;
2273			int32 MaxRow = 0;
2274			for (const FSkillNodeRef& Node : Nodes)
2275			{
2276				if (Node.Tree == Tree)
2277				{
2278					MaxColumn = FMath::Max(MaxColumn, Node.Column);
2279					MaxRow = FMath::Max(MaxRow, Node.Row);
2280				}
2281			}
2282			const float Pad = bTreeCyber ? 22.f * S : 9.f * P;
2283			// The spell tree names its four element columns above the nodes.
2284			const float ColumnHeadH = bTreeCyber ? 0.f : 8.f * P;
2285			const float GridY = GridTop + ColumnHeadH;
2286			const float CellW = (AreaW - 2.f * Pad) / (MaxColumn + 1);
2287			const float CellH = FMath::Min(bTreeCyber ? 104.f * S : 29.f * P, (AreaY + AreaH - Pad - GridY) / (MaxRow + 1));
2288			const float BoxW = FMath::Max(20.f * S, CellW - (bTreeCyber ? 18.f * S : 5.f * P));
2289			const float BoxH = FMath::Max(20.f * S, CellH - (bTreeCyber ? 22.f * S : 4.f * P));
2290			auto BoxPos = [&](const FSkillNodeRef& Node)
2291			{
2292				return FVector2D(AX + Pad + Node.Column * CellW + (CellW - BoxW) * 0.5f, GridY + Node.Row * CellH);
2293			};
2294			if (!bTreeCyber)
2295			{
2296				for (int32 Column = 0; Column <= MaxColumn; ++Column)
2297				{
2298					const float ColX = AX + Pad + Column * CellW + CellW * 0.5f;
2299					const FLinearColor EC = GBHudText::ElementColor(GBHudMenuDraw::SpellColumnElement(Column));
2300					const FString Label = FString(GBHudMenuDraw::SpellColumnName(Column)).ToUpper();
2301					const int32 Small = FMath::Max(2, FMath::RoundToInt(P * 0.5f));
2302					const float LW = MeasurePixelText(Label, Small).X;
2303					RpgGem(ColX - LW * 0.5f - 5.f * P, GridTop + 2.5f * P, EC, true);
2304					FPixelTextStyle Lab;
2305					Lab.Scale = Small;
2306					Lab.Color = EC;
2307					Lab.Shadow = FLinearColor(0.f, 0.f, 0.f, 0.9f);
2308					DrawPixelText(Label, ColX + 2.f * P, GridTop, Lab, 0.5f);
2309				}
2310			}
2311	
2312			// Requirement links first, under the boxes: down from the parent, across in the gap above the child, down.
2313			for (const FSkillNodeRef& Node : Nodes)
2314			{
2315				const FGBSkillNodeDefinition* Def = (Node.Tree == Tree && Data) ? Data->FindSkillNode(Node.Id) : nullptr;
2316				if (!Def)
2317				{
2318					continue;
2319				}
2320				for (const FName& Req : Def->Requires)
2321				{
2322					const FSkillNodeRef* ReqNode = Nodes.FindByPredicate([&Req](const FSkillNodeRef& Other) { return Other.Id == Req; });
2323					if (!ReqNode || ReqNode->Tree != Tree)
2324					{
2325						continue;
2326					}
2327					const FVector2D A = BoxPos(*ReqNode) + FVector2D(BoxW * 0.5f, BoxH);
2328					const FVector2D B = BoxPos(Node) + FVector2D(BoxW * 0.5f, 0.f);
2329					const bool bOwned = SkillTree->GetRank(Req) > 0;
2330					const float ElbowY = FMath::RoundToFloat(B.Y - (CellH - BoxH) * 0.5f);
2331					if (bTreeCyber)
2332					{
2333						const FLinearColor LinkColor = bOwned ? GBCy::Red : GBAlpha(GBCy::Grey, 0.45f);
2334						const float T = FMath::Max(1.f, FMath::RoundToFloat((bOwned ? 2.f : 1.f) * S));
2335						FillRect(A.X - T * 0.5f, A.Y, T, ElbowY - A.Y, LinkColor);
2336						FillRect(FMath::Min(A.X, B.X) - T * 0.5f, ElbowY - T * 0.5f, FMath::Abs(B.X - A.X) + T, T, LinkColor);
2337						FillRect(B.X - T * 0.5f, ElbowY, T, B.Y - ElbowY, LinkColor);
2338						FillRect(B.X - 3.f * S, B.Y - 6.f * S, 6.f * S, 6.f * S, LinkColor);
2339						if (bOwned)
2340						{
2341							// A data pulse running down the owned link.
2342							const float Len = (ElbowY - A.Y) + FMath::Abs(B.X - A.X) + (B.Y - ElbowY);
2343							const float D = FMath::Frac((float)GetRealTime() * 0.6f + A.X * 0.001f) * Len;
2344							FVector2D Dot;
2345							if (D < ElbowY - A.Y) { Dot = FVector2D(A.X, A.Y + D); }
2346							else if (D < ElbowY - A.Y + FMath::Abs(B.X - A.X)) { Dot = FVector2D(A.X + FMath::Sign(B.X - A.X) * (D - (ElbowY - A.Y)), ElbowY); }
2347							else { Dot = FVector2D(B.X, ElbowY + (D - (ElbowY - A.Y) - FMath::Abs(B.X - A.X))); }
2348							DrawGlow(Dot.X, Dot.Y, 8.f * S, 8.f * S, GBAlpha(GBCy::RedBright, 0.9f));
2349						}
2350					}
2351					else
2352					{
2353						// A gilt chain two art pixels wide with a dark keyline.
2354						const float T = 2.f * P;
2355						const float AX2 = FMath::RoundToFloat((A.X - P) / P) * P;
2356						const float BX2 = FMath::RoundToFloat((B.X - P) / P) * P;
2357						const float EY = FMath::RoundToFloat(ElbowY / P) * P;
2358						const FLinearColor Core = bOwned ? GBRpg::Gold3 : GBRpg::Iron1;
2359						auto Seg = [&](float SX, float SY, float SW, float SH)
2360						{
2361							FillRect(SX - P, SY - P, SW + 2.f * P, SH + 2.f * P, GBRpg::Outline);
2362						};
2363						auto SegCore = [&](float SX, float SY, float SW, float SH) { FillRect(SX, SY, SW, SH, Core); };
2364						Seg(AX2, A.Y, T, EY - A.Y);
2365						Seg(FMath::Min(AX2, BX2), EY, FMath::Abs(BX2 - AX2) + T, T);
2366						Seg(BX2, EY, T, B.Y - EY);
2367						SegCore(AX2, A.Y, T, EY - A.Y);
2368						SegCore(FMath::Min(AX2, BX2), EY, FMath::Abs(BX2 - AX2) + T, T);
2369						SegCore(BX2, EY, T, B.Y - EY);
2370					}
2371				}
2372			}
2373			for (const FSkillNodeRef& Node : Nodes)
2374			{
2375				if (Node.Tree != Tree)
2376				{
2377					continue;
2378				}
2379				const FVector2D Pos = BoxPos(Node);
2380				DrawSkillNode(Player, Tree, Node.Id, Pos.X, Pos.Y, BoxW, BoxH);
2381				AddMenuHit(EMenuHitKind::SkillNode, Pos.X, Pos.Y, BoxW, BoxH, 0, Node.Id);
2382			}
2383			(void)TreeSkin;
2384		}
2385	
2386		// Details of the selected node, in its tree's skin.
2387		if (Selected)
2388		{
2389			const EGBHudSkin DetailSkin = Selected->Tree == 0 ? EGBHudSkin::Rpg90s : EGBHudSkin::Cyberpunk;
2390			const float DY = AreaY + AreaH + 12.f * S;
2391			const FGBSkillNodeDefinition* Def = Data ? Data->FindSkillNode(Selected->Id) : nullptr;
2392			const int32 Rank = SkillTree->GetRank(Selected->Id);
2393			const EGBSkillUnlockResult Can = SkillTree->CanUnlock(Selected->Id);
2394			const FString Status = Can == EGBSkillUnlockResult::Ok ? FString() : SkillResultText(Data, Selected->Id, Can);
2395			const FString Meta = FString::Printf(TEXT("Rank %d / %d    Cost %d"), Rank, Def ? Def->MaxRank : 1, Def ? Def->Cost : 0);
2396			if (DetailSkin == EGBHudSkin::Cyberpunk)
2397			{
2398				CyBox(X, DY, W, DetailH, 16.f * S, GBAlpha(GBCy::Ink, 0.92f), GBAlpha(GBCy::Red, 0.9f), 0x5);
2399				FillRect(X, DY + 14.f * S, 4.f * S, DetailH - 28.f * S, GBCy::Red);
2400				const FVector2D NS = UiText(DetailSkin, EGBTextSize::Heading, EGBTextTone::Accent, SkillName(Data, Selected->Id), X + 26.f * S, DY + 14.f * S);
2401				UiText(DetailSkin, EGBTextSize::Small, EGBTextTone::Value, Meta, X + 26.f * S + NS.X + 20.f * S, DY + 24.f * S);
2402				if (Def)
2403				{
2404					UiWrapped(DetailSkin, EGBTextSize::Body, EGBTextTone::Normal, Def->Description, X + 26.f * S, DY + 22.f * S + NS.Y, W * 0.62f);
2405				}
2406				if (Can == EGBSkillUnlockResult::Ok)
2407				{
2408					TArray<TPair<FString, FString>> Actions;
2409					Actions.Add(TPair<FString, FString>(TEXT("Enter"), TEXT("Unlock")));
2410					MenuHints(DetailSkin, Actions, X + W - 26.f * S, DY + DetailH - 40.f * S, 1.f);
2411				}
2412				else
2413				{
2414					UiText(DetailSkin, EGBTextSize::Small, EGBTextTone::Warn, Status.ToUpper(), X + W - 26.f * S, DY + DetailH - 38.f * S, 1.f);
2415				}
2416			}
2417			else
2418			{
2419				const float PX = FMath::RoundToFloat(X / P) * P;
2420				const float PY = FMath::RoundToFloat(DY / P) * P;
2421				const float PW = FMath::RoundToFloat(W / P) * P;
2422				const float PH = FMath::RoundToFloat(DetailH / P) * P;
2423				FillRect(PX, PY, PW, PH, GBRpg::Stone1);
2424				RpgStone(PX, PY, PW, PH);
2425				RpgFrame(PX, PY, PW, PH, ERpgFrame::Gold);
2426				const FVector2D NS = UiText(DetailSkin, EGBTextSize::Heading, EGBTextTone::Accent, SkillName(Data, Selected->Id), PX + 7.f * P, PY + 6.f * P);
2427				UiText(DetailSkin, EGBTextSize::Small, EGBTextTone::Muted, Meta, PX + 7.f * P + NS.X + 8.f * P, PY + 6.f * P + NS.Y - 7.f * FMath::Max(2, FMath::RoundToInt(P * 0.5f)));
2428				if (Def)
2429				{
2430					UiWrapped(DetailSkin, EGBTextSize::Body, EGBTextTone::Normal, Def->Description, PX + 7.f * P, PY + 10.f * P + NS.Y, PW * 0.62f);
2431				}
2432				if (Can == EGBSkillUnlockResult::Ok)
2433				{
2434					TArray<TPair<FString, FString>> Actions;
2435					Actions.Add(TPair<FString, FString>(TEXT("Enter"), TEXT("Unlock")));
2436					MenuHints(DetailSkin, Actions, PX + PW - 7.f * P, PY + PH - 15.f * P, 1.f);
2437				}
2438				else
2439				{
2440					UiText(DetailSkin, EGBTextSize::Small, EGBTextTone::Warn, Status, PX + PW - 7.f * P, PY + PH - 10.f * P, 1.f);
2441				}
2442			}
2443		}

