234	void AGBHUD::ApplyMenuHover(const FMenuHit& Hit)
235	{
236		switch (Hit.Kind)
237		{
238		case EMenuHitKind::PauseEntry:
239		case EMenuHitKind::ItemRow:
240		case EMenuHitKind::WeaponRow:
241			MenuState.Cursor = Hit.Index;
242			break;
243		case EMenuHitKind::SpellSlot:
244			if (!MenuState.bChoosingSpell)
245			{
246				MenuState.Cursor = Hit.Index;
247			}
248			break;
249		case EMenuHitKind::SpellChoice:
250			MenuState.SubCursor = Hit.Index;
251			break;
252		case EMenuHitKind::SkillNode:
253			MenuState.SkillCursor = Hit.Id;
254			break;
255		case EMenuHitKind::Tab:
256		case EMenuHitKind::SkillReset:
257		case EMenuHitKind::SkillAddPoint:
258		default:
259			// Tabs, the skill buttons (reset, +1 point) and the death screen only react to clicks.
260			break;
261		}
262	}
263	
264	void AGBHUD::ActivateMenuHit(const FMenuHit& Hit)
265	{
266		AGBPlayerCharacter* Player = GetPlayer();
267		switch (Hit.Kind)
268		{
269		case EMenuHitKind::PauseEntry:
270			MenuState.Cursor = Hit.Index;
271			MenuConfirm();
272			break;
273		case EMenuHitKind::Tab:
274			if (Hit.Index != MenuState.Page)
275			{
276				SetInventoryPage(Hit.Index);
277			}
278			break;
279		case EMenuHitKind::ItemRow:
280			MenuState.Cursor = Hit.Index;
281			ConfirmItem(Player);
282			break;
283		case EMenuHitKind::WeaponRow:
284			MenuState.Cursor = Hit.Index;
285			ConfirmWeapon(Player);
286			break;
287		case EMenuHitKind::SpellSlot:
288			// A click on another slot while choosing leaves the chooser and opens it for that slot.
289			MenuState.bChoosingSpell = false;
290			MenuState.Cursor = Hit.Index;
291			ConfirmSpellSlot(Player);
292			break;
293		case EMenuHitKind::SpellChoice:
294			MenuState.SubCursor = Hit.Index;
295			ConfirmSpellSlot(Player);
296			break;
297		case EMenuHitKind::SkillNode:
298			MenuState.SkillCursor = Hit.Id;
299			ConfirmSkill(Player);
300			break;
301		case EMenuHitKind::SkillReset:
302			ResetSkills(Player);
303			break;
304		case EMenuHitKind::SkillAddPoint:
305			AddTestSkillPoint(Player);
306			break;
307		case EMenuHitKind::DeathScreen:
308			// The controller handles the respawn confirm (AGBPlayerController::InputMenuClick): nothing here,
309			// so a click respawns exactly once.
310			break;
311		}
312	}
