param([string]$Tag = 'ui1')
$root = 'C:\GameJam'
$lock = Join-Path $root 'Glyphbound\Saved\machine.lock'
$s = $PSScriptRoot
if (Test-Path $lock) {
    $age = (Get-Date) - (Get-Item $lock).LastWriteTime
    if ($age.TotalMinutes -lt 45) { Write-Host "LOCKED: $(Get-Content $lock)"; exit 3 }
}
Set-Content -Path $lock -Value "shotgun/ui chat | build + ui smoke | $([DateTime]::UtcNow.ToString('u'))" -Encoding ascii
try {
    powershell -NoProfile -File (Join-Path $root 'Tools\Jam\Build-Jam.ps1') | Select-Object -Last 12
    if ($LASTEXITCODE -ne 0) { Write-Host 'BUILD FAILED'; exit 1 }
    powershell -NoProfile -File (Join-Path $root 'Tools\Jam\Smoke-Jam.ps1') -Only ui -Offscreen -ResX 1920 -ResY 1080 | Select-String 'LogGB: (Error|Warning)|Smoke:|screenshots:'
    $d = Join-Path $root 'Glyphbound\Saved\Screenshots\Smoke'
    $out = Join-Path $s $Tag
    New-Item -ItemType Directory -Force $out | Out-Null
    Get-ChildItem $d -Filter 'ui_*.png' | Copy-Item -Destination $out -Force
} finally {
    Remove-Item $lock -Force -ErrorAction SilentlyContinue
}

